VALUES
  ('rs1801133', 'MTHFR', '1', 11856378, 'health', 'MTHFR C677T - Cardiovascular & Folate', 'Common variant affecting folate metabolism. Associated with elevated homocysteine levels, which may increase cardiovascular risk. Supplementing with methylfolate can help.', '{"CC":{"risk":"typical","meaning":"Normal MTHFR enzyme activity"},"CT":{"risk":"slightly_elevated","meaning":"~65% enzyme activity. Mildly elevated homocysteine. Consider methylfolate."},"TT":{"risk":"elevated","meaning":"~30% enzyme activity. Significantly elevated homocysteine. Methylfolate supplementation recommended."}}'::jsonb, '[{"name":"SNPedia","url":"https://www.snpedia.com/index.php/Rs1801133"},{"name":"ClinVar","id":"VCV000003520"}]'::jsonb, 'high', 3),
  ('rs1801131', 'MTHFR', '1', 11854476, 'health', 'MTHFR A1298C', 'Second common MTHFR variant. Milder effect than C677T but compounds with it. Affects folate and BH4 metabolism.', '{"AA":{"risk":"typical","meaning":"Normal"},"AC":{"risk":"typical","meaning":"Mild reduction in enzyme activity"},"CC":{"risk":"slightly_elevated","meaning":"Reduced enzyme activity, especially if combined with C677T variant"}}'::jsonb, '[{"name":"SNPedia","url":"https://www.snpedia.com/index.php/Rs1801131"}]'::jsonb, 'high', 2),
  ('rs10757274', '9p21', '9', 22096055, 'health', 'Coronary Artery Disease Risk', 'Located in the 9p21 region, one of the strongest genetic risk factors for coronary artery disease identified by GWAS.', '{"AA":{"risk":"typical","meaning":"Average risk"},"AG":{"risk":"slightly_elevated","meaning":"~25% increased risk for CAD"},"GG":{"risk":"elevated","meaning":"~50% increased risk for CAD"}}'::jsonb, '[{"name":"GWAS Catalog","id":"GCST000025"},{"name":"SNPedia","url":"https://www.snpedia.com/index.php/Rs10757274"}]'::jsonb, 'high', 3),
  ('rs1333049', '9p21.3', '9', 22125504, 'health', 'Heart Disease Risk (9p21)', 'Strong GWAS-identified variant for coronary heart disease. The C allele increases risk.', '{"GG":{"risk":"typical","meaning":"Lower risk"},"GC":{"risk":"slightly_elevated","meaning":"Moderate increased risk"},"CC":{"risk":"elevated","meaning":"Significantly increased risk (~1.6x)"}}'::jsonb, '[{"name":"GWAS Catalog","id":"GCST000038"}]'::jsonb, 'high', 4),
  ('rs4961', 'ADD1', '4', 2906707, 'health', 'Salt-Sensitive Hypertension', 'Variant in the alpha-adducin gene associated with salt sensitivity and blood pressure response.', '{"GG":{"risk":"typical","meaning":"Normal salt sensitivity"},"GT":{"risk":"slightly_elevated","meaning":"Moderate salt sensitivity"},"TT":{"risk":"elevated","meaning":"High salt sensitivity — blood pressure more affected by sodium intake"}}'::jsonb, '[{"name":"SNPedia","url":"https://www.snpedia.com/index.php/Rs4961"}]'::jsonb, 'moderate', 3),
  ('rs5186', 'AGTR1', '3', 148459988, 'health', 'Hypertension Risk', 'Angiotensin II receptor variant. The C allele is associated with increased blood pressure and cardiovascular risk.', '{"AA":{"risk":"typical","meaning":"Normal risk"},"AC":{"risk":"slightly_elevated","meaning":"Moderately increased hypertension risk"},"CC":{"risk":"elevated","meaning":"Higher risk of hypertension and cardiovascular events"}}'::jsonb, '[{"name":"SNPedia","url":"https://www.snpedia.com/index.php/Rs5186"}]'::jsonb, 'moderate', 3),
  ('rs7903146', 'TCF7L2', '10', 114758349, 'health', 'Type 2 Diabetes Risk', 'Strongest known genetic risk factor for type 2 diabetes. The T allele impairs insulin secretion from pancreatic beta cells.', '{"CC":{"risk":"typical","meaning":"Average risk for T2D"},"CT":{"risk":"slightly_elevated","meaning":"~1.4x increased risk"},"TT":{"risk":"elevated","meaning":"~2x increased risk for type 2 diabetes"}}'::jsonb, '[{"name":"GWAS Catalog","id":"GCST000568"},{"name":"SNPedia","url":"https://www.snpedia.com/index.php/Rs7903146"}]'::jsonb, 'high', 4),
  ('rs5219', 'KCNJ11', '11', 17409572, 'health', 'Type 2 Diabetes (KCNJ11)', 'Variant in a potassium channel gene expressed in pancreatic beta cells. Affects insulin secretion.', '{"CC":{"risk":"typical","meaning":"Normal insulin secretion"},"CT":{"risk":"slightly_elevated","meaning":"Mildly impaired insulin secretion"},"TT":{"risk":"slightly_elevated","meaning":"Impaired insulin secretion, ~1.2x T2D risk"}}'::jsonb, '[{"name":"SNPedia","url":"https://www.snpedia.com/index.php/Rs5219"}]'::jsonb, 'high', 3),
  ('rs13266634', 'SLC30A8', '8', 118184783, 'health', 'Type 2 Diabetes (Zinc Transporter)', 'Zinc transporter in pancreatic beta cells. Affects insulin storage and secretion.', '{"CC":{"risk":"typical","meaning":"Average risk"},"CT":{"risk":"slightly_elevated","meaning":"Moderately increased T2D risk"},"TT":{"risk":"elevated","meaning":"Higher T2D risk, ~1.5x"}}'::jsonb, '[{"name":"GWAS Catalog","id":"GCST000573"}]'::jsonb, 'high', 3),
  ('rs429358', 'APOE', '19', 44908684, 'health', 'Alzheimer''s Risk (APOE e4)', 'One of two SNPs defining APOE genotype. The C allele (e4) is the strongest known genetic risk factor for late-onset Alzheimer''s disease.', '{"TT":{"risk":"typical","meaning":"No e4 allele — average Alzheimer''s risk"},"TC":{"risk":"elevated","meaning":"One e4 allele — 3-4x increased risk"},"CC":{"risk":"elevated","meaning":"Two e4 alleles — 8-12x increased risk"}}'::jsonb, '[{"name":"SNPedia","url":"https://www.snpedia.com/index.php/Rs429358"},{"name":"ClinVar","id":"VCV000078920"}]'::jsonb, 'high', 5),
  ('rs7412', 'APOE', '19', 44908822, 'health', 'APOE e2/e3/e4 Determination', 'Together with rs429358, determines APOE genotype. The T allele (e2) is protective against Alzheimer''s.', '{"CC":{"risk":"typical","meaning":"e3 or e4 — depends on rs429358"},"CT":{"risk":"typical","meaning":"Carries one e2 allele — potentially protective"},"TT":{"risk":"typical","meaning":"e2/e2 — protective against Alzheimer''s, but increased lipid risk"}}'::jsonb, '[{"name":"SNPedia","url":"https://www.snpedia.com/index.php/Rs7412"}]'::jsonb, 'high', 4),
  ('rs1799950', 'BRCA1', '17', 43091983, 'health', 'BRCA1 Breast Cancer', 'Variant in the BRCA1 tumor suppressor gene. Certain variants significantly increase breast and ovarian cancer risk.', '{"AA":{"risk":"typical","meaning":"Normal BRCA1 function"},"AG":{"risk":"elevated","meaning":"One copy of risk variant — discuss with genetic counselor"},"GG":{"risk":"elevated","meaning":"Two copies — significantly elevated cancer risk"}}'::jsonb, '[{"name":"ClinVar","id":"VCV000055608"},{"name":"SNPedia","url":"https://www.snpedia.com/index.php/Rs1799950"}]'::jsonb, 'high', 4),
  ('rs1799966', 'BRCA1', '17', 43071077, 'health', 'BRCA1 D1692N', 'Missense variant in BRCA1. Generally classified as benign/likely benign but monitored.', '{"AA":{"risk":"typical","meaning":"Reference allele"},"AG":{"risk":"typical","meaning":"Heterozygous — usually benign"},"GG":{"risk":"typical","meaning":"Homozygous variant — usually benign"}}'::jsonb, '[{"name":"ClinVar","id":"VCV000055616"}]'::jsonb, 'moderate', 2),
  ('rs1042522', 'TP53', '17', 7579472, 'health', 'TP53 Cancer Susceptibility', 'Common variant in the tumor suppressor p53 gene. The Pro72 (C) allele may increase cancer susceptibility in some populations.', '{"GG":{"risk":"typical","meaning":"Arg/Arg — better at inducing apoptosis"},"GC":{"risk":"typical","meaning":"Arg/Pro — intermediate"},"CC":{"risk":"slightly_elevated","meaning":"Pro/Pro — slightly less efficient tumor suppression in some contexts"}}'::jsonb, '[{"name":"SNPedia","url":"https://www.snpedia.com/index.php/Rs1042522"}]'::jsonb, 'moderate', 3),
  ('rs6983267', '8q24', '8', 128413305, 'health', 'Colorectal Cancer Risk', 'Located in the 8q24 cancer susceptibility region. The G allele increases colorectal cancer risk.', '{"TT":{"risk":"typical","meaning":"Lower risk"},"TG":{"risk":"slightly_elevated","meaning":"Moderate increased risk"},"GG":{"risk":"elevated","meaning":"~1.5x increased colorectal cancer risk"}}'::jsonb, '[{"name":"GWAS Catalog","id":"GCST000308"}]'::jsonb, 'high', 3),
  ('rs1447295', '8q24', '8', 128554220, 'health', 'Prostate Cancer Risk', 'Variant in the 8q24 locus associated with prostate cancer susceptibility.', '{"CC":{"risk":"typical","meaning":"Average risk"},"CA":{"risk":"slightly_elevated","meaning":"Moderately increased risk"},"AA":{"risk":"elevated","meaning":"Significantly increased prostate cancer risk (~1.6x)"}}'::jsonb, '[{"name":"GWAS Catalog","id":"GCST000036"}]'::jsonb, 'high', 3),
  ('rs2476601', 'PTPN22', '1', 114377568, 'health', 'Autoimmune Disease Susceptibility', 'Major autoimmune gene. The A allele increases risk for type 1 diabetes, rheumatoid arthritis, lupus, and other autoimmune conditions.', '{"GG":{"risk":"typical","meaning":"Normal immune regulation"},"GA":{"risk":"slightly_elevated","meaning":"~1.5x risk for multiple autoimmune diseases"},"AA":{"risk":"elevated","meaning":"Higher autoimmune susceptibility"}}'::jsonb, '[{"name":"SNPedia","url":"https://www.snpedia.com/index.php/Rs2476601"},{"name":"GWAS Catalog","id":"GCST000130"}]'::jsonb, 'high', 4),
  ('rs3135388', 'HLA-DRB1', '6', 32681049, 'health', 'Multiple Sclerosis Risk', 'Tag SNP for HLA-DRB1*15:01, the strongest genetic risk factor for multiple sclerosis.', '{"CC":{"risk":"typical","meaning":"No HLA risk allele"},"CT":{"risk":"slightly_elevated","meaning":"One copy — ~3x MS risk"},"TT":{"risk":"elevated","meaning":"Two copies — significantly elevated MS risk"}}'::jsonb, '[{"name":"GWAS Catalog","id":"GCST000424"}]'::jsonb, 'high', 4),
  ('rs2104286', 'IL2RA', '10', 6099045, 'health', 'Type 1 Diabetes & MS Risk', 'Interleukin-2 receptor alpha chain variant. Associated with multiple autoimmune conditions.', '{"AA":{"risk":"typical","meaning":"Normal IL2R expression"},"AG":{"risk":"slightly_elevated","meaning":"Moderate autoimmune risk"},"GG":{"risk":"slightly_elevated","meaning":"Increased risk for T1D and MS"}}'::jsonb, '[{"name":"GWAS Catalog","id":"GCST000341"}]'::jsonb, 'high', 3),
  ('rs6265', 'BDNF', '11', 27679916, 'health', 'BDNF Val66Met - Depression & Anxiety', 'Brain-derived neurotrophic factor variant. Affects synaptic plasticity and is associated with depression, anxiety, and stress response.', '{"CC":{"risk":"typical","meaning":"Val/Val — normal BDNF secretion"},"CT":{"risk":"slightly_elevated","meaning":"Val/Met — reduced activity-dependent BDNF secretion"},"TT":{"risk":"elevated","meaning":"Met/Met — significantly reduced BDNF secretion, higher depression/anxiety risk"}}'::jsonb, '[{"name":"SNPedia","url":"https://www.snpedia.com/index.php/Rs6265"}]'::jsonb, 'high', 3),
  ('rs4680', 'COMT', '22', 19963748, 'health', 'COMT Val158Met - Stress & Cognition', 'Catechol-O-methyltransferase variant. Affects dopamine breakdown in the prefrontal cortex. Influences stress resilience, pain sensitivity, and cognitive style.', '{"GG":{"risk":"typical","meaning":"Val/Val (Warrior) — faster dopamine clearance, better under stress but lower baseline cognition"},"AG":{"risk":"typical","meaning":"Val/Met — intermediate, balanced profile"},"AA":{"risk":"typical","meaning":"Met/Met (Worrier) — slower dopamine clearance, higher cognition but more stress-sensitive"}}'::jsonb, '[{"name":"SNPedia","url":"https://www.snpedia.com/index.php/Rs4680"}]'::jsonb, 'high', 3),
  ('rs25531', 'SLC6A4', '17', 30237328, 'health', 'Serotonin Transporter', 'Affects serotonin transporter expression. The short allele (A/G) is associated with higher anxiety and stress sensitivity.', '{"AA":{"risk":"typical","meaning":"Long/Long — normal serotonin reuptake"},"AG":{"risk":"slightly_elevated","meaning":"Long/Short — moderate stress sensitivity"},"GG":{"risk":"slightly_elevated","meaning":"Short/Short equivalent — higher anxiety susceptibility"}}'::jsonb, '[{"name":"SNPedia","url":"https://www.snpedia.com/index.php/Rs25531"}]'::jsonb, 'moderate', 3),
  ('rs6025', 'F5', '1', 169549811, 'health', 'Factor V Leiden (Blood Clotting)', 'Most common inherited thrombophilia. Increases risk of deep vein thrombosis and pulmonary embolism.', '{"CC":{"risk":"typical","meaning":"No Factor V Leiden — normal clotting"},"CT":{"risk":"elevated","meaning":"Heterozygous — 5-10x increased DVT risk"},"TT":{"risk":"elevated","meaning":"Homozygous — 50-100x increased DVT risk"}}'::jsonb, '[{"name":"ClinVar","id":"VCV000000683"},{"name":"SNPedia","url":"https://www.snpedia.com/index.php/Rs6025"}]'::jsonb, 'high', 5),
  ('rs1799963', 'F2', '11', 46761055, 'health', 'Prothrombin G20210A', 'Second most common inherited thrombophilia after Factor V Leiden.', '{"GG":{"risk":"typical","meaning":"Normal prothrombin levels"},"GA":{"risk":"elevated","meaning":"Heterozygous — 3-4x increased clotting risk"},"AA":{"risk":"elevated","meaning":"Homozygous — significantly elevated clotting risk"}}'::jsonb, '[{"name":"ClinVar","id":"VCV000000684"},{"name":"SNPedia","url":"https://www.snpedia.com/index.php/Rs1799963"}]'::jsonb, 'high', 5),
  ('rs2187668', 'HLA-DQ2.5', '6', 32713854, 'health', 'Celiac Disease Risk', 'Tag SNP for HLA-DQ2.5, present in ~95% of celiac disease patients. Necessary but not sufficient for celiac.', '{"CC":{"risk":"typical","meaning":"No DQ2.5 — very low celiac risk"},"CT":{"risk":"slightly_elevated","meaning":"One copy DQ2.5 — predisposed but may never develop celiac"},"TT":{"risk":"elevated","meaning":"Two copies — highest genetic risk for celiac disease"}}'::jsonb, '[{"name":"GWAS Catalog","id":"GCST000612"}]'::jsonb, 'high', 4),
  ('rs1061170', 'CFH', '1', 196659237, 'health', 'Age-Related Macular Degeneration', 'Complement factor H variant. Y402H is the strongest genetic risk factor for AMD, the leading cause of vision loss in older adults.', '{"TT":{"risk":"typical","meaning":"Normal AMD risk"},"TC":{"risk":"slightly_elevated","meaning":"~2.5x AMD risk"},"CC":{"risk":"elevated","meaning":"~6x AMD risk — regular eye exams important"}}'::jsonb, '[{"name":"SNPedia","url":"https://www.snpedia.com/index.php/Rs1061170"},{"name":"GWAS Catalog","id":"GCST000074"}]'::jsonb, 'high', 4),
  ('rs1800562', 'HFE', '6', 26093141, 'health', 'Hereditary Hemochromatosis (C282Y)', 'Most common cause of hereditary hemochromatosis (iron overload). Homozygous C282Y causes clinical disease in many individuals.', '{"GG":{"risk":"typical","meaning":"No hemochromatosis risk from this variant"},"GA":{"risk":"typical","meaning":"Carrier — usually no clinical impact"},"AA":{"risk":"elevated","meaning":"Homozygous — high risk of iron overload, regular monitoring needed"}}'::jsonb, '[{"name":"ClinVar","id":"VCV000009551"},{"name":"SNPedia","url":"https://www.snpedia.com/index.php/Rs1800562"}]'::jsonb, 'high', 5),
  ('rs1799945', 'HFE', '6', 26091179, 'health', 'Hemochromatosis (H63D)', 'Milder hemochromatosis variant. Compound heterozygosity with C282Y increases risk.', '{"CC":{"risk":"typical","meaning":"Normal iron metabolism"},"CG":{"risk":"typical","meaning":"Carrier — monitor if also C282Y carrier"},"GG":{"risk":"slightly_elevated","meaning":"Homozygous — mild increased iron absorption"}}'::jsonb, '[{"name":"ClinVar","id":"VCV000009550"}]'::jsonb, 'high', 3),
  ('rs12913832', 'HERC2', '15', 28365618, 'traits', 'Eye Color', 'Primary determinant of blue vs. brown eye color. This SNP in the HERC2 gene controls OCA2 expression, the key gene for eye pigmentation.', '{"AA":{"risk":"typical","meaning":"Brown eyes (most likely)"},"AG":{"risk":"typical","meaning":"Green or hazel eyes likely"},"GG":{"risk":"typical","meaning":"Blue eyes (very likely — 99% prediction accuracy)"}}'::jsonb, '[{"name":"SNPedia","url":"https://www.snpedia.com/index.php/Rs12913832"}]'::jsonb, 'high', 4),
  ('rs1800407', 'OCA2', '15', 28230318, 'traits', 'Eye Color Modifier', 'Modifies eye color determination. Can shift brown toward hazel/green.', '{"CC":{"risk":"typical","meaning":"No color modification"},"CT":{"risk":"typical","meaning":"May contribute to green/hazel"},"TT":{"risk":"typical","meaning":"Strong shift toward blue/green"}}'::jsonb, '[{"name":"SNPedia","url":"https://www.snpedia.com/index.php/Rs1800407"}]'::jsonb, 'high', 3),
  ('rs1805007', 'MC1R', '16', 89919709, 'traits', 'Red Hair', 'One of several MC1R variants associated with red hair, fair skin, and freckling.', '{"CC":{"risk":"typical","meaning":"Not a red hair carrier from this variant"},"CT":{"risk":"typical","meaning":"Red hair carrier — may have reddish tint"},"TT":{"risk":"typical","meaning":"Likely red hair if combined with other MC1R variants"}}'::jsonb, '[{"name":"SNPedia","url":"https://www.snpedia.com/index.php/Rs1805007"}]'::jsonb, 'high', 4),
  ('rs1805008', 'MC1R', '16', 89919736, 'traits', 'Red Hair & Fair Skin', 'MC1R variant strongly associated with red hair and sun sensitivity.', '{"CC":{"risk":"typical","meaning":"Not a carrier"},"CT":{"risk":"typical","meaning":"Carrier — possible red/auburn tones"},"TT":{"risk":"typical","meaning":"Strong red hair contributor"}}'::jsonb, '[{"name":"SNPedia","url":"https://www.snpedia.com/index.php/Rs1805008"}]'::jsonb, 'high', 3),
  ('rs12821256', 'KITLG', '12', 89328335, 'traits', 'Blonde Hair', 'Associated with blonde hair in Europeans. The C allele reduces KITLG expression in hair follicles.', '{"TT":{"risk":"typical","meaning":"Darker hair likely"},"TC":{"risk":"typical","meaning":"May contribute to lighter hair"},"CC":{"risk":"typical","meaning":"Blonde hair contributor"}}'::jsonb, '[{"name":"GWAS Catalog","id":"GCST001283"}]'::jsonb, 'high', 3),
  ('rs762551', 'CYP1A2', '15', 75041917, 'traits', 'Caffeine Metabolism Speed', 'Determines how fast you metabolize caffeine. Fast metabolizers clear caffeine quickly; slow metabolizers feel effects longer.', '{"AA":{"risk":"typical","meaning":"Fast metabolizer — caffeine cleared quickly, less likely to disrupt sleep"},"AC":{"risk":"typical","meaning":"Moderate metabolizer"},"CC":{"risk":"typical","meaning":"Slow metabolizer — caffeine lingers longer, more likely to cause jitters and sleep disruption"}}'::jsonb, '[{"name":"SNPedia","url":"https://www.snpedia.com/index.php/Rs762551"}]'::jsonb, 'high', 3),
  ('rs671', 'ALDH2', '12', 112241766, 'traits', 'Alcohol Flush Reaction', 'Extremely common in East Asian populations. The A allele causes acetaldehyde buildup, leading to facial flushing after drinking alcohol.', '{"GG":{"risk":"typical","meaning":"Normal alcohol metabolism"},"GA":{"risk":"typical","meaning":"Partial flush — red face after 1-2 drinks, increased esophageal cancer risk with regular drinking"},"AA":{"risk":"typical","meaning":"Severe flush — very unpleasant reaction to alcohol, strong cancer risk if drinking regularly"}}'::jsonb, '[{"name":"SNPedia","url":"https://www.snpedia.com/index.php/Rs671"}]'::jsonb, 'high', 5),
  ('rs713598', 'TAS2R38', '7', 141972804, 'traits', 'Bitter Taste Perception (PTC)', 'Determines sensitivity to bitter compounds like PTC and PROP. Supertasters find broccoli, coffee, and beer more bitter.', '{"GG":{"risk":"typical","meaning":"PAV/PAV — Supertaster, very sensitive to bitter"},"GC":{"risk":"typical","meaning":"PAV/AVI — Medium taster"},"CC":{"risk":"typical","meaning":"AVI/AVI — Non-taster, low bitter sensitivity"}}'::jsonb, '[{"name":"SNPedia","url":"https://www.snpedia.com/index.php/Rs713598"}]'::jsonb, 'high', 3),
  ('rs1726866', 'TAS2R38', '7', 141973545, 'traits', 'Bitter Taste (TAS2R38 2nd)', 'Second variant determining PTC/PROP bitter taste perception.', '{"CC":{"risk":"typical","meaning":"Taster allele"},"CT":{"risk":"typical","meaning":"Intermediate tasting"},"TT":{"risk":"typical","meaning":"Non-taster allele"}}'::jsonb, '[{"name":"SNPedia","url":"https://www.snpedia.com/index.php/Rs1726866"}]'::jsonb, 'high', 3),
  ('rs4988235', 'MCM6/LCT', '2', 136608646, 'traits', 'Lactose Tolerance', 'Determines adult lactose tolerance. The T allele allows continued lactase production into adulthood (lactase persistence).', '{"CC":{"risk":"typical","meaning":"Lactose intolerant — lactase production declines in adulthood"},"CT":{"risk":"typical","meaning":"Lactose tolerant — can digest dairy"},"TT":{"risk":"typical","meaning":"Lactose tolerant — full lactase persistence"}}'::jsonb, '[{"name":"SNPedia","url":"https://www.snpedia.com/index.php/Rs4988235"}]'::jsonb, 'high', 4),
  ('rs1144566', 'CLOCK', '4', 56336940, 'traits', 'Sleep Chronotype (CLOCK)', 'Variant in the CLOCK gene affecting circadian rhythm. Influences whether you are naturally a morning person or night owl.', '{"AA":{"risk":"typical","meaning":"Tendency toward morning chronotype"},"AG":{"risk":"typical","meaning":"Intermediate chronotype"},"GG":{"risk":"typical","meaning":"Tendency toward evening chronotype — natural night owl"}}'::jsonb, '[{"name":"SNPedia","url":"https://www.snpedia.com/index.php/Rs1144566"}]'::jsonb, 'moderate', 2),
  ('rs12927162', 'PER2', '2', 239153445, 'traits', 'Sleep Chronotype (PER2)', 'Period circadian protein variant. Affects internal clock timing.', '{"GG":{"risk":"typical","meaning":"Typical circadian timing"},"GA":{"risk":"typical","meaning":"Slight morning tendency"},"AA":{"risk":"typical","meaning":"Strong morning lark tendency"}}'::jsonb, '[{"name":"GWAS Catalog","id":"GCST002039"}]'::jsonb, 'moderate', 2),
  ('rs1815739', 'ACTN3', '11', 66560624, 'traits', 'Muscle Fiber Type (Sprint vs Endurance)', 'The "speed gene." ACTN3 determines fast-twitch muscle fiber composition. Found in virtually all Olympic sprinters (RR genotype).', '{"CC":{"risk":"typical","meaning":"RR — Full alpha-actinin-3 in fast-twitch fibers. Sprint/power advantage."},"CT":{"risk":"typical","meaning":"RX — Intermediate. Balanced power and endurance."},"TT":{"risk":"typical","meaning":"XX — No alpha-actinin-3. Natural endurance advantage. Found in ~18% of population."}}'::jsonb, '[{"name":"SNPedia","url":"https://www.snpedia.com/index.php/Rs1815739"}]'::jsonb, 'high', 3),
  ('rs1799971', 'OPRM1', '6', 154360797, 'traits', 'Pain Sensitivity & Opioid Response', 'Mu-opioid receptor variant. Affects pain perception and response to opioid medications.', '{"AA":{"risk":"typical","meaning":"Normal pain sensitivity and opioid response"},"AG":{"risk":"typical","meaning":"Somewhat reduced opioid sensitivity — may need higher doses"},"GG":{"risk":"typical","meaning":"Significantly reduced opioid response — discuss with anesthesiologist"}}'::jsonb, '[{"name":"SNPedia","url":"https://www.snpedia.com/index.php/Rs1799971"}]'::jsonb, 'high', 3),
  ('rs1042725', 'HMGA2', '12', 66220755, 'traits', 'Height', 'One of many SNPs associated with human height. HMGA2 has the largest individual effect.', '{"CC":{"risk":"typical","meaning":"Slightly taller tendency (~0.4 cm per allele)"},"CT":{"risk":"typical","meaning":"Average effect"},"TT":{"risk":"typical","meaning":"Slightly shorter tendency"}}'::jsonb, '[{"name":"GWAS Catalog","id":"GCST000147"}]'::jsonb, 'high', 2),
  ('rs4911414', 'IRF4', '6', 391406, 'traits', 'Freckling', 'Interferon regulatory factor 4 variant. Associated with freckling and sun sensitivity.', '{"GG":{"risk":"typical","meaning":"Less likely to freckle"},"GT":{"risk":"typical","meaning":"Moderate freckling tendency"},"TT":{"risk":"typical","meaning":"More likely to freckle"}}'::jsonb, '[{"name":"GWAS Catalog","id":"GCST001509"}]'::jsonb, 'moderate', 2),
  ('rs17822931', 'ABCC11', '16', 48258198, 'traits', 'Earwax Type & Body Odor', 'Determines wet vs dry earwax and apocrine sweat gland activity. Dry earwax (common in East Asians) correlates with less body odor.', '{"CC":{"risk":"typical","meaning":"Wet earwax, normal body odor"},"CT":{"risk":"typical","meaning":"Wet earwax (dominant)"},"TT":{"risk":"typical","meaning":"Dry earwax, reduced body odor — may not need deodorant"}}'::jsonb, '[{"name":"SNPedia","url":"https://www.snpedia.com/index.php/Rs17822931"}]'::jsonb, 'high', 3),
  ('rs72921001', 'OR6A2', '11', 6886653, 'traits', 'Cilantro Taste Preference', 'Olfactory receptor variant determining whether cilantro tastes like fresh herbs or like soap.', '{"CC":{"risk":"typical","meaning":"Cilantro tastes normal/herbal"},"CA":{"risk":"typical","meaning":"May detect slight soapy notes"},"AA":{"risk":"typical","meaning":"Cilantro likely tastes soapy/metallic"}}'::jsonb, '[{"name":"SNPedia","url":"https://www.snpedia.com/index.php/Rs72921001"}]'::jsonb, 'moderate', 3),
  ('rs4481887', 'OR2M7', '1', 248432554, 'traits', 'Asparagus Smell Detection', 'Determines whether you can smell the characteristic odor in urine after eating asparagus.', '{"GG":{"risk":"typical","meaning":"Can smell asparagus metabolites"},"GA":{"risk":"typical","meaning":"Reduced ability"},"AA":{"risk":"typical","meaning":"Cannot detect asparagus smell in urine"}}'::jsonb, '[{"name":"GWAS Catalog","id":"GCST001686"}]'::jsonb, 'moderate', 2),
  ('rs10427255', 'Near ZEB2', '2', 145413233, 'traits', 'Photic Sneeze Reflex', 'Determines whether bright light triggers sneezing (ACHOO syndrome). Affects 18-35% of people.', '{"CC":{"risk":"typical","meaning":"Normal — no photic sneeze reflex"},"CT":{"risk":"typical","meaning":"May have mild sun-sneeze reflex"},"TT":{"risk":"typical","meaning":"Likely has photic sneeze reflex"}}'::jsonb, '[{"name":"GWAS Catalog","id":"GCST000780"}]'::jsonb, 'moderate', 2),
  ('rs1799853', 'CYP2C9', '10', 96702047, 'pharmacogenomics', 'Warfarin Sensitivity (CYP2C9*2)', 'Cytochrome P450 2C9 variant. Affects metabolism of warfarin, NSAIDs, and many other drugs. Slow metabolizers need lower doses.', '{"CC":{"risk":"typical","meaning":"Normal metabolizer — standard warfarin dose"},"CT":{"risk":"slightly_elevated","meaning":"Intermediate metabolizer — may need ~20% lower warfarin dose"},"TT":{"risk":"elevated","meaning":"Poor metabolizer — may need ~50% lower warfarin dose"}}'::jsonb, '[{"name":"ClinVar","id":"VCV000001918"},{"name":"SNPedia","url":"https://www.snpedia.com/index.php/Rs1799853"}]'::jsonb, 'high', 4),
  ('rs1057910', 'CYP2C9', '10', 96741053, 'pharmacogenomics', 'Warfarin Sensitivity (CYP2C9*3)', 'More impactful CYP2C9 variant for warfarin. *3 allele reduces enzyme activity by ~95%.', '{"AA":{"risk":"typical","meaning":"Normal metabolizer"},"AC":{"risk":"elevated","meaning":"Intermediate metabolizer — significantly reduced warfarin dose needed"},"CC":{"risk":"elevated","meaning":"Poor metabolizer — warfarin dose may be 75% lower than standard"}}'::jsonb, '[{"name":"ClinVar","id":"VCV000001919"}]'::jsonb, 'high', 5),
