  ('rs3892097', 'CYP2D6', '22', 42526694, 'pharmacogenomics', 'CYP2D6 Drug Metabolism', 'Major drug metabolism enzyme. Affects processing of codeine, tramadol, tamoxifen, many antidepressants, and ~25% of all prescribed drugs.', '{"CC":{"risk":"typical","meaning":"Normal/extensive metabolizer"},"CT":{"risk":"typical","meaning":"Intermediate metabolizer — some drugs less effective or need dose adjustment"},"TT":{"risk":"elevated","meaning":"Poor metabolizer — codeine ineffective (cannot convert to morphine), may need alternative drugs"}}'::jsonb, '[{"name":"ClinVar","id":"VCV000000253"},{"name":"SNPedia","url":"https://www.snpedia.com/index.php/Rs3892097"}]'::jsonb, 'high', 5),
